def gws(*args):
    out = subprocess.run([GWS, *args], capture_output=True, text=True)
    if out.returncode != 0:
        sys.exit("gws-work 執行失敗：\n" + out.stderr + out.stdout)
    start = out.stdout.find("{")
    return json.loads(out.stdout[start:])


def read(rng):
    return gws("sheets", "spreadsheets", "values", "get",
               "--params", json.dumps({"spreadsheetId": SHEET, "range": rng})).get("values", [])



rows = read("Products!A1:D260")
where = {}
for i, r in enumerate(rows):
    if r and re.fullmatch(r"\d+", str(r[0]).strip()):
        where[int(r[0])] = (i + 1, r + [""] * (4 - len(r)))
data, skipped = [], []
for pid_s, c in sorted(CHANGES.items(), key=lambda kv: int(kv[0])):
    pid = int(pid_s)
    if pid not in where:
        skipped.append("找不到編號 %d" % pid); continue
    rownum, r = where[pid]
    cur = (r[1], r[2], r[3])
    if tuple(x.strip() for x in cur) != tuple(x.strip() for x in c["old"]):
        skipped.append("編號 %d 第 %d 列跟預期不同（可能你手動改過），跳過：表上是 %s" % (pid, rownum, cur)); continue
    labels = ["分類", "品名", "規格"]
    diffs = ["%s：%s → %s" % (labels[k], c["old"][k] or "（空白）", c["new"][k]) for k in range(3) if c["old"][k] != c["new"][k]]
    print("第 %d 列（編號 %d）｜" % (rownum, pid) + "；".join(diffs))
    data.append({"range": "Products!B%d:D%d" % (rownum, rownum), "values": [list(c["new"])]})
if skipped:
    print("\n跳過：\n" + "\n".join(skipped))
print("\n共 %d 筆要修改" % len(data))
if not WRITE:
    sys.exit("（只檢查，沒有寫入。確認沒問題後，在指令最後加上 --write 再跑一次）")
gws("sheets", "spreadsheets", "values", "batchUpdate",
    "--params", json.dumps({"spreadsheetId": SHEET}),
    "--json", json.dumps({"valueInputOption": "RAW", "data": data}))
check = read("Products!A1:D260")
ok = 0
for d in data:
    rownum = int(re.search(r"B(\d+)", d["range"]).group(1))
    got = (check[rownum - 1] + [""] * 4)[1:4]
    if [x.strip() for x in got] == [x.strip() for x in d["values"][0]]:
        ok += 1
    else:
        print("⚠️ 第 %d 列讀回是 %s" % (rownum, got))
print("寫入並驗證完成：%d / %d 筆" % (ok, len(data)))
